-- KÖRS INTE AUTOMATISKT. Migrationen körs mot databasen först efter Mattias ja.
-- Ingen individdata lagras i tabellen (LUM-17).

create table if not exists public.social_posts (
  id               uuid primary key default gen_random_uuid(),
  varumarke        text not null,
  kanal            text not null,
  pelare           text,
  text             text,
  ai_markning      text not null,
  granskare        text,
  barken_status    text not null default 'utkast',
  rattighetsstatus text not null default 'oklar',
  utm              text,
  planerad_tid     timestamptz,
  status           text not null default 'utkast',
  skapad           timestamptz not null default now(),
  uppdaterad       timestamptz not null default now(),

  constraint social_posts_kanal_giltig check (kanal in
    ('instagram','facebook','youtube','threads','bluesky','linkedin','nyhetsbrev','spotify')),
  constraint social_posts_barken_status_giltig check (barken_status in
    ('utkast','granskas','godkand','stoppad')),
  constraint social_posts_rattighetsstatus_giltig check (rattighetsstatus in
    ('oklar','klar','ej_tillamplig')),
  constraint social_posts_status_giltig check (status in
    ('utkast','godkand','schemalagd','publicerad','pausad')),

  -- Grindspärren: inget schemaläggs eller publiceras utan Barkens godkännande,
  -- klar rättighetsstatus, namngiven granskare och AI-märkning.
  constraint social_posts_grindsparr check (
    status not in ('schemalagd','publicerad')
    or (
      barken_status = 'godkand'
      and rattighetsstatus in ('klar','ej_tillamplig')
      and granskare is not null and btrim(granskare) <> ''
      and btrim(ai_markning) <> ''
    )
  )
);

create index if not exists social_posts_varumarke_idx on public.social_posts (varumarke);
create index if not exists social_posts_planerad_tid_idx on public.social_posts (planerad_tid);

create or replace function public.social_posts_satt_uppdaterad()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.uppdaterad := now();
  return new;
end $$;

drop trigger if exists social_posts_uppdaterad on public.social_posts;
create trigger social_posts_uppdaterad before update on public.social_posts
  for each row execute function public.social_posts_satt_uppdaterad();

-- Åtkomst: radskydd på och inga policyer. Då når bara servernyckeln tabellen.
-- Läsning för "inloggade i teamet" läggs till som policy när teamrollen är definierad;
-- alla inloggade besökare är inte teamet.
alter table public.social_posts enable row level security;
revoke all on public.social_posts from anon, authenticated;

